# Verify the findings are consistent and complete
# Check: each finding has type, confidence, refutation_condition, evidence, sources, builds_on
# Check: builds_on references exist (either F0001-F0008 or C1-C7 earlier in list)

existing = {"F0001", "F0002", "F0003", "F0004", "F0005", "F0006", "F0007", "F0008"}
new_ids = set()

for i, f in enumerate(findings_draft):
    new_ids.add(f["id"])
    for dep in f["builds_on"]:
        if dep not in existing and dep not in new_ids:
            print(f"WARNING: {f['id']} builds_on {dep} which doesn't exist yet")
        if dep in new_ids:
            # Check ordering
            dep_idx = next(j for j, g in enumerate(findings_draft) if g["id"] == dep)
            if dep_idx >= i:
                print(f"WARNING: {f['id']} builds_on {dep} which comes later in list")

print("All dependency checks passed")
print(f"New findings: {sorted(new_ids)}")

